questionvariables.text:
/* Randomize intercept positions */
x_val : rand([2, 3, 4, 5, 6, 7]);
y_val : rand([2, 3, 4, 5, 6, 7]);

/* Randomize line styles and shading directions */
vert_solid : rand([true, false]);
horiz_solid : rand([true, false]);
shade_right : rand([true, false]);
shade_above : rand([true, false]);

/* Variables passed to JSXGraph */
is_vert_solid_js : if vert_solid then 1 else 0;
is_horiz_solid_js : if horiz_solid then 1 else 0;
is_shade_right_js : if shade_right then 1 else 0;
is_shade_above_js : if shade_above then 1 else 0;

/* Determine the target vertical inequality */
ta1_ge : x >= x_val;
ta1_g  : x > x_val;
ta1_le : x <= x_val;
ta1_l  : x < x_val;
ta1 : if shade_right then (if vert_solid then ta1_ge else ta1_g) else (if vert_solid then ta1_le else ta1_l);
ta1_wrong : if shade_right then (if vert_solid then ta1_g else ta1_ge) else (if vert_solid then ta1_l else ta1_le);

/* Determine the target horizontal inequality */
ta2_ge : y >= y_val;
ta2_g  : y > y_val;
ta2_le : y <= y_val;
ta2_l  : y < y_val;
ta2 : if shade_above then (if horiz_solid then ta2_ge else ta2_g) else (if horiz_solid then ta2_le else ta2_l);
ta2_wrong : if shade_above then (if horiz_solid then ta2_g else ta2_ge) else (if horiz_solid then ta2_l else ta2_le);

/* Text variables for the worked solution */
v_style : if vert_solid then "solid" else "dashed";
h_style : if horiz_solid then "solid" else "dashed";
v_shade : if shade_right then "right" else "left";
h_shade : if shade_above then "above" else "below";
v_val_str : if shade_right then (if vert_solid then "greater than or equal to" else "greater than") else (if vert_solid then "less than or equal to" else "less than");
h_val_str : if shade_above then (if horiz_solid then "greater than or equal to" else "greater than") else (if horiz_solid then "less than or equal to" else "less than");
